from produire import produire,paras,steps,table
parts=[
('La {subluxation atlanto-axoïdienne rhumatoïde} est une instabilité entre les deux premières vertèbres cervicales liée à la polyarthrite rhumatoïde. Elle peut menacer la moelle et la jonction craniovertébrale. La douleur n’en mesure pas toujours la gravité.',paras('L’inflammation peut endommager ligaments et surfaces articulaires. Le déplacement peut varier avec la position, expliquant qu’une image neutre seule soit parfois insuffisante.', 'D’autres atteintes rhumatoïdes cervicales existent, notamment subaxiales et ascension de l’odontoïde. Elles doivent être recherchées dans le bilan sans confondre toutes les anomalies avec la seule subluxation antérieure.')),
('Le {terrain rhumatoïde motive la vigilance}. Une polyarthrite ancienne, séropositive et érosive est un contexte évocateur. L’absence de plainte importante n’exclut pas une atteinte cervicale.',paras('Le support HUG insiste sur ce terrain et sur l’imagerie en cas de cervicalgie. Les fréquences élevées rapportées dans des séries anciennes ne sont pas une estimation de la prévalence suisse actuelle sous traitements modernes.', 'Rechercher antécédent de lésion cervicale et examens antérieurs. Avant un geste nécessitant une mobilisation du cou, transmettre toute instabilité connue à l’équipe concernée.')),
('Le {mécanisme associe inflammation et instabilité}. La synovite et le pannus peuvent éroder l’os et altérer les ligaments. Le déplacement et les tissus inflammatoires réduisent parfois l’espace disponible pour la moelle.',paras('Le ligament transverse contribue à la stabilité de la relation entre atlas et odontoïde. Sa défaillance permet un déplacement anormal.', 'Le pannus peut comprimer même si un intervalle osseux paraît rassurant à la radiographie. L’IRM permet d’évaluer tissus mous et structures neurologiques au-delà des seuls repères osseux.')),
('Le {tri recherche une atteinte médullaire ou bulbaire}. Faiblesse, maladresse, troubles de marche ou décharges aux mouvements sont préoccupants. Un déficit récent ou progressif impose un avis urgent.',paras('Troubles sphinctériens, difficulté respiratoire ou de déglutition et signes neurologiques nouveaux renforcent l’urgence. Éviter les mobilisations provocatrices ; organiser une évaluation spécialisée et la protection du rachis adaptée.', 'Ne pas réaliser de manipulation cervicale ni demander une flexion forcée pour démontrer le diagnostic. La sécurité prime sur l’obtention d’une image dynamique.')),
('L’{anamnèse explore douleur et fonction neurologique}. Rechercher douleur cervicale haute ou occipitale, sensation d’instabilité et symptômes aux changements de position. Interroger aussi les activités fines et la marche.',paras('Demander ancienneté et activité de la polyarthrite, traitements de fond, corticothérapie, chirurgie antérieure et antécédents de lésions cervicales. Une atteinte périphérique des mains peut masquer une maladresse médullaire.', 'Préparer les interventions prévues : anesthésie, intubation ou soins impliquant une position du cou. Signaler les symptômes et imageries disponibles sans improviser un test de mobilité.')),
('L’{examen associe neurologie et précautions mécaniques}. Évaluer motricité, sensibilité, réflexes et marche si elle est sûre. Rechercher signes pyramidaux et atteinte des nerfs crâniens.',paras('Les déformations articulaires périphériques peuvent compliquer l’interprétation de la force et de la fonction. Confronter plusieurs signes plutôt qu’un test isolé.', 'Un examen normal n’exclut pas une instabilité. Ne pas tester sa réductibilité manuellement ni provoquer les symptômes par flexion répétée.')),
('L’{approche syndromique sépare inflammation, instabilité et compression}. Ces composantes peuvent coexister. Une simple douleur ne permet pas de déterminer la sécurité mécanique.',table(['Composante','Question clinique'],[['Inflammation rhumatoïde.','La maladie de fond est-elle active et traitée ?'],['Instabilité.','Existe-t-il un déplacement pathologique ou une destruction menaçante ?'],['Compression.','Moelle, jonction craniovertébrale ou structures bulbaires sont-elles menacées ?'],['Cause concurrente.','Fracture, infection, dégénérescence ou dépôts cristallins expliquent-ils mieux le tableau ?']])) ,
('Le {diagnostic nécessite une imagerie adaptée}. Les radiographies peuvent documenter les rapports osseux et leur variation. L’IRM recherche pannus et compression.',paras('La recommandation EULAR citée par HUG et la revue européenne propose des clichés de profil neutre et en flexion en cas de suspicion clinique. Leur réalisation doit être décidée et encadrée ; elle n’autorise pas un mouvement forcé devant un tableau dangereux.', 'Si la radiographie est anormale ou si des signes neurologiques spécifiques sont présents, l’IRM est indiquée. Une radiographie neutre normale ne suffit pas si la suspicion persiste.')),
('Les {examens précisent l’anatomie avant décision}. Le scanner décrit les érosions et les rapports osseux complexes. L’IRM complète l’analyse des tissus et de la moelle.',paras('La revue européenne explique que des mesures radiographiques rassurantes peuvent méconnaître un pannus compressif. Les différentes mesures ne doivent pas être utilisées isolément comme seuil universel de chirurgie.', 'Les clichés dynamiques sont réservés aux situations jugées sûres par l’équipe. En cas de déficit, douleur sévère ou suspicion d’instabilité majeure, privilégier l’avis spécialisé et l’imagerie sans provocation.')),
('L’{algorithme protège la moelle avant de tester la mobilité}. La suspicion naît du terrain et des symptômes. La stratégie d’imagerie dépend ensuite de la gravité.',steps('Identifier polyarthrite, douleur haute et signes neurologiques ou bulbaires.', 'Si menace neurologique, éviter mobilisation et obtenir avis urgent avec imagerie adaptée.', 'Si situation stable, organiser bilan radiographique et éventuelle étude dynamique encadrée.', 'Compléter par IRM en cas de signes neurologiques ou d’anomalie ; scanner selon question osseuse.', 'Décider traitement rhumatologique, protection et éventuelle stabilisation avec l’équipe du rachis.')),
('La {prise en charge suisse associe rhumatologie et chirurgie du rachis}. Le contrôle de l’inflammation est important. Il ne corrige pas nécessairement une instabilité mécanique déjà constituée.',paras('Une compression, une progression ou une instabilité menaçante peut nécessiter stabilisation et parfois décompression. La décision dépend de l’examen, des images, du terrain et des objectifs du patient.', 'Les traitements de fond de la polyarthrite sont ajustés par le rhumatologue ; aucun schéma unique ni dose non vérifiée n’est proposé ici. L’antalgie ne prouve pas la stabilité et ne remplace pas l’évaluation mécanique.', 'Informer l’anesthésiste avant intubation ou positionnement. Collier, modalités de transfert et mouvement autorisé sont décidés selon la lésion ; ne pas transposer automatiquement les conseils de mobilisation d’une cervicalgie commune.')),
('Le {suivi surveille évolution et sécurité des gestes}. Toute aggravation neurologique nécessite une réévaluation rapide. Les contrôles cliniques et radiologiques sont individualisés.',paras('Conserver les comptes rendus et signaler l’instabilité aux soignants. Expliquer quels symptômes imposent une consultation urgente et quels mouvements éviter en attendant les consignes.', 'La rééducation tient compte de la stabilité ou d’une fixation éventuelle. L’amélioration de la polyarthrite périphérique n’autorise pas à oublier une lésion cervicale connue.')),
('Le {point clé} est de protéger la jonction cervicale haute. Une image neutre ou une douleur faible ne suffit pas à exclure le danger. L’évaluation doit intégrer os, ligaments, pannus et moelle.',paras('Les clichés dynamiques sont un outil encadré, pas un exercice à reproduire. Traitement de l’inflammation et correction de l’instabilité répondent à deux objectifs complémentaires.'))]
quiz=[('Quelles vertèbres sont concernées ?','L’atlas et l’axis, les deux premières vertèbres cervicales.'),('La douleur mesure-t-elle toujours le risque ?','Non.'),('Quel terrain est évocateur ?','Une polyarthrite rhumatoïde ancienne, séropositive et érosive.'),('Quel ligament contribue à la stabilité ?','Le ligament transverse.'),('Un pannus peut-il comprimer sans anomalie osseuse majeure apparente ?','Oui.'),('Quels symptômes imposent une évaluation urgente ?','Déficit nouveau ou progressif, signes médullaires ou bulbaires.'),('Faut-il forcer la flexion pour confirmer ?','Non.'),('Une radiographie neutre normale suffit-elle toujours ?','Non.'),('Quand demander une IRM ?','Notamment si signes neurologiques ou radiographie anormale.'),('Quel est l’apport du scanner ?','Décrire l’os et les rapports anatomiques complexes.'),('Un seuil radiographique isolé décide-t-il toute chirurgie ?','Non.'),('Un traitement de fond répare-t-il toujours l’instabilité ?','Non.'),('Pourquoi informer l’anesthésiste ?','Pour adapter intubation et positionnement au risque cervical.'),('Les exercices d’une cervicalgie commune sont-ils automatiquement adaptés ?','Non, la stabilité doit être prise en compte.')]
produire(10,parts,quiz,(1,24))
